package com.example.starter.incident;

/**
 * 共享资源租约状态机：ACTIVE → RELEASED 或 ACTIVE → REVOKED。
 * RELEASED（任务完成/取消时原子释放）与 REVOKED（被更高严重级别事件抢占撤销）
 * 均为终态；状态流转时版本加 1。
 */
public enum LeaseStatus {

    /** 生效中；任务须持有 ACTIVE 租约才能标记 STARTED。 */
    ACTIVE,

    /** 已释放（任务完成或取消时原子释放）。 */
    RELEASED,

    /** 已撤销（被更高严重级别事件的抢占计划原子撤销）。 */
    REVOKED;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 共享资源定义实体，对应 shared_resources 表。
 * resourceKey 全局唯一；capacity 为正整数容量（单位数），
 * 该资源上 ACTIVE 租约的单位合计永不超过 capacity。时间均为 UTC。
 */
public record SharedResource(
        long id,
        String resourceKey,
        int capacity,
        String createdBy,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 共享资源租约实体，对应 resource_leases 表。
 * leaseKey 全局唯一，同键同内容幂等、同键不同内容冲突；
 * 同一任务对同一资源至多一条 ACTIVE 租约。
 * version 为乐观版本：创建为 1，释放/撤销时加 1，抢占计划按 leaseKey+version 指定受害租约。
 * releasedAt 仅 RELEASED 有值，revokedAt 仅 REVOKED 有值。时间均为 UTC。
 */
public record ResourceLease(
        long id,
        String leaseKey,
        long resourceId,
        long incidentId,
        long taskId,
        int units,
        LeaseStatus status,
        long version,
        String requestId,
        String createdBy,
        Instant createdAt,
        Instant updatedAt,
        Instant releasedAt,
        Instant revokedAt) {

    /**
     * 判断两条租约申请的业务内容是否一致（用于 leaseKey 幂等比对）。
     */
    public boolean sameContent(long resourceId, long taskId, int units) {
        return this.resourceId == resourceId && this.taskId == taskId && this.units == units;
    }
}

