        // 任务版本不一致
        assertApiStatus(() -> requestLease("INC-V1", "T-1", "alice", "RES-V", "LK-1", 1,
                task.version() + 1), HttpStatus.CONFLICT);
        // 必填字段为空
        assertApiStatus(() -> resourceService.requestLease("INC-V1", "T-1", "alice",
