                .andExpect(status().isOk())
                .andExpect(jsonPath("$.resourceKey").value("RES-L"))
                .andExpect(jsonPath("$.leases.length()").value(1))
                .andExpect(jsonPath("$.leases[0].status").value("ACTIVE"));
